def slowest_pace(pages, hours):
    lo, hi = 1, max(pages)
    while lo < hi:
        mid = (lo + hi) // 2
        needed = sum((p + mid - 1) // mid for p in pages)
        if needed <= hours:
            hi = mid
        else:
            lo = mid + 1
    return lo

