function slowest_pace(pages, hours) {
  let lo = 1;
  let hi = Math.max(...pages);
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    let needed = 0;
    for (const p of pages) needed += Math.ceil(p / mid);
    if (needed <= hours) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

