class Solution {
    public int slowestPace(int[] pages, int hours) {
        int lo = 1, hi = 1;
        for (int p : pages) hi = Math.max(hi, p);
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long needed = 0;
            for (int p : pages) needed += (p + mid - 1) / mid;
            if (needed <= hours) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

